use vstd::prelude::*;

verus! {

fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
    ensures
        numbers.len() == 0 || numbers.len() == 1 ==> result == numbers,
        numbers.len() > 1 ==> {
            &&& result.len() == 2 * numbers.len() - 1
            &&& forall|i: int| 0 <= i < numbers.len() ==> result[2 * i] == numbers[i]
            &&& forall|i: int| 0 <= i < numbers.len() - 1 ==> result[2 * i + 1] == delimiter
        },
{
    if numbers.len() == 0 || numbers.len() == 1 {
        return numbers;
    }

    let mut result: Vec<i8> = Vec::new();
    let mut idx: usize = 0;

    while idx < numbers.len()
        invariant
            0 <= idx <= numbers.len(),
            numbers.len() > 1,
            idx == 0 ==> result.len() == 0,
            idx > 0 ==> {
                &&& result.len() == 2 * idx - 1
                &&& forall|i: int| 0 <= i < idx ==> result[2 * i] == numbers[i]
                &&& forall|i: int| 0 <= i < idx - 1 ==> result[2 * i + 1] == delimiter
            },
        decreases numbers.len() - idx,
    {
        result.push(numbers[idx]);
        
        assert(result.len() == if idx == 0 { 1 } else { 2 * idx });
        assert(result[2 * idx] == numbers[idx]);
        
        if idx < numbers.len() - 1 {
            result.push(delimiter);
            
            assert(result.len() == 2 * idx + 2);
            assert(result[2 * idx + 1] == delimiter);
        }
        
        idx = idx + 1;
    }

    assert(idx == numbers.len());
    assert(result.len() == 2 * numbers.len() - 1);
    
    result
}

}

